raw.css:
:root{--color-bg:#faf6f3;--color-bg-alt:#f0e6e0;--color-text:#3b2f2f;--color-text-light:#6b5a58;--color-primary-dark:#8c3a4b;--color-primary-darker:#6f2d3a;--color-accent-on-dark:#f2c6ce;--color-dark-bg:#3b2330;--color-border:#d9c7c2;--color-white:#ffffff;--font-body:Georgia,'Times New Roman',serif;--font-heading:'Palatino Linotype','Book Antiqua',Georgia,serif;--radius:0.5rem;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--max-width:75rem;}
*,*::before,*::after{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;font-family:var(--font-body);color:var(--color-text);background-color:var(--color-bg);line-height:1.6;font-size:1rem;}
h1,h2,h3,h4{font-family:var(--font-heading);color:var(--color-primary-darker);line-height:1.2;margin-top:0;}
p{margin-top:0;margin-bottom:var(--space-sm);}
a{color:var(--color-primary-dark);text-decoration:underline;}
a:hover{color:var(--color-primary-darker);}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--color-primary-darker);outline-offset:2px;}
img{max-width:100%;height:auto;display:block;}
.container{max-width:var(--max-width);margin-left:auto;margin-right:auto;padding-left:1.25rem;padding-right:1.25rem;width:100%;}

header{background-color:var(--color-bg);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-sm);padding-top:var(--space-sm);padding-bottom:var(--space-sm);}
.logo{font-family:'Palatino Linotype','Book Antiqua',serif;font-variant:small-caps;font-weight:400;letter-spacing:0.25em;font-size:clamp(1.1rem,4vw,1.6rem);color:var(--color-primary-darker);text-decoration:none;border-bottom:1px solid var(--color-primary-darker);width:fit-content;padding-bottom:0.15rem;}
.logo:hover{color:var(--color-primary-dark);}
nav[aria-label="Main"] .nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
nav[aria-label="Main"] a{text-decoration:none;color:var(--color-text);font-size:0.95rem;padding:0.5rem 0.25rem;}
nav[aria-label="Main"] a:hover{color:var(--color-primary-dark);}

main{display:block;}
section{padding-top:var(--space-xl);padding-bottom:var(--space-xl);}
section.alt-bg{background-color:var(--color-bg-alt);}
section.dark-bg{background-color:var(--color-dark-bg);color:var(--color-accent-on-dark);}
section.dark-bg h2,section.dark-bg h3{color:var(--color-accent-on-dark);}

.grid{display:grid;grid-template-columns:1fr;gap:var(--space-md);}

.card{background-color:var(--color-white);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}

.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0.75rem 1.5rem;background-color:var(--color-primary-dark);color:var(--color-white);border:none;border-radius:var(--radius);text-decoration:none;font-size:1rem;cursor:pointer;}
.btn:hover{background-color:var(--color-primary-darker);}
.btn:focus-visible{outline:3px solid var(--color-accent-on-dark);outline-offset:2px;}

form{display:flex;flex-direction:column;gap:var(--space-sm);max-width:40rem;}
.form-group{display:flex;flex-direction:column;gap:0.35rem;}
label{font-weight:bold;}
input,textarea,select{min-height:44px;padding:0.6rem 0.75rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:var(--color-white);color:var(--color-text);}
textarea{min-height:8rem;resize:vertical;}
input:focus,textarea:focus,select:focus{border-color:var(--color-primary-dark);}

footer{background-color:var(--color-dark-bg);color:var(--color-accent-on-dark);padding-top:var(--space-lg);padding-bottom:var(--space-lg);}
footer a{color:var(--color-accent-on-dark);}
.footer-inner p{margin:0 0 0.5rem 0;}
.footer-brand{font-family:var(--font-heading);font-variant:small-caps;letter-spacing:0.15em;}
.copyright{font-size:0.85rem;opacity:0.85;}

@media (max-width:600px){
  .header-inner{flex-direction:column;align-items:flex-start;}
  nav[aria-label="Main"] .nav-list{flex-direction:column;gap:0.25rem;width:100%;}
  section{padding-top:var(--space-lg);padding-bottom:var(--space-lg);}
  .btn{width:100%;}
}

@media (min-width:601px){
  .grid-2{grid-template-columns:repeat(2,1fr);}
  .grid-3{grid-template-columns:repeat(3,1fr);}
  .grid-4{grid-template-columns:repeat(4,1fr);}
  nav[aria-label="Main"] .nav-list{flex-wrap:nowrap;}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  *{animation:none !important;transition:none !important;}
}

